function AliPayDesktopShortcutManager:_registerFirstLoginAutoPopup(popStage)
    local firstLoginCheckPoint = PopupCheckPoint.ALIPAY_DESKTOP_SHORTCUT_FIRST_LOGIN
    self._autoPopupMgr:registerPopup({
        checkPoint = firstLoginCheckPoint,
        stages = { popStage.STAGE_TWO, popStage.STAGE_FOUR },
        check = function()
            local canPopup = self:_getAutoPopupState(
                AliPayDesktopShortcutManager.FIRST_LOGIN_AUTO_POP_CACHE_KEY,
                false
            )
            return canPopup
        end,
        creator = function(_, onPopOver)
            return self:_createAutoPopupCreator(
                onPopOver,
                AliPayDesktopShortcutManager.FIRST_LOGIN_AUTO_POP_CACHE_KEY,
                firstLoginCheckPoint,
                false
            )
        end,
    })
    return firstLoginCheckPoint
end

function AliPayDesktopShortcutManager:_registerStreakBreakAutoPopup(popStage)
    local streakBreakCheckPoint = PopupCheckPoint.ALIPAY_DESKTOP_SHORTCUT_STREAK_BREAK
    self._autoPopupMgr:registerPopup({
        checkPoint = streakBreakCheckPoint,
        stages = { popStage.STAGE_TWO, popStage.STAGE_FOUR },
        check = function()
            local canPopup = self:_getAutoPopupState(
                AliPayDesktopShortcutManager.STREAK_BREAK_AUTO_POP_CACHE_KEY,
                true
            )
            local firstLoginCanPopup = self:_getAutoPopupState(
                AliPayDesktopShortcutManager.FIRST_LOGIN_AUTO_POP_CACHE_KEY,
                false
            )
            local inCountdown = callIfExists(self._model, "isDeskTopVisitStreakBreak") == true
            canPopup = canPopup and not firstLoginCanPopup and inCountdown
            return canPopup
        end,
        creator = function(_, onPopOver)
            return self:_createAutoPopupCreator(
                onPopOver,
                AliPayDesktopShortcutManager.STREAK_BREAK_AUTO_POP_CACHE_KEY,
                streakBreakCheckPoint,
                true
            )
        end,
    })
    return streakBreakCheckPoint
end

function PromotionEvent2025Manager:tryAutoPopPromotionCardPack()
    if not self:_hasPendingPromotionCardPacks() then return end

    local function onHandleOver()
        AutoPopEventCenter:dispatch(AutoPopEvent.SINGLE_POP_OVER, PopupCheckPoint.PROMOTION_CARD_PACK_POP_STAGE4)
    end


    local creator = function()
        _G.amfBean("CollectCardManager"):skipThisRoundCardPackOpen()
        _G.amfTransaction(TransactionEvent.COLLECT_CARD_FLOW, {
            flowType = _G.COLLECT_CARD_FLOW_TYPE.OPEN_AND_SETTLE,
            rewards = self._pendingPromotionCardPackList,
            openAnimPanelConfig = {title = "晋级赛奖励"},
            onComplete = function()
                self._pendingPromotionCardPackList = {}
                onHandleOver()
            end,
            onError = function()
                self._pendingPromotionCardPackList = {}
                onHandleOver()
            end,
        })
    end

    self._autoPopupMgr:addPopupConfig(PopupCheckPoint.PROMOTION_CARD_PACK_POP_STAGE4, creator)
end

function MeMeFoxManager:_registerAutoPopup()
    local autoPopupMgr = _G.amfBean("AutoPopupMgr", true)
    if not autoPopupMgr then return end
    self._autoPopCheckPoint = autoPopupMgr:registerPopup({
        checkPoint = PopupCheckPoint.CONTINUOUS_TARGET_CHECK,
        stages = {AutoPopupConst.PopStage.STAGE_THREE},
        actId = 4042,
        check = function()
            return self:stage3OrInLevelCanPop() == true
        end,
        pop = function(stageParams, onPopOver)
            -- check/pop 收到的是强弹场景事件对象，事件数据要经 getData 取。
            local nextLevelModeData = (stageParams:getData() or {}).nextLevelModeData
            self:cleanPopReason()
            return self:_createStage3PopupCreator({
                source = 3,
                autoPlayNextLevel = nextLevelModeData and nextLevelModeData.autoPlayNextLevel or false,
            }, onPopOver)
        end,
    })
end
